question:
      'What to say in an interview when interviewer asks what is virtual DOM?',
    answers: [
      `


  🧠 
  "The Virtual DOM is a lightweight, in-memory representation of the real DOM. 
  It's one of the key performance optimizations behind libraries like React. 
  Instead of manipulating the browser DOM directly every time something changes, 
  React updates a virtual DOM first. It then uses a process called 'diffing' 
  to compare the new virtual DOM with the previous one, 
  and calculates the minimal number of actual DOM operations needed. 
  This selective update process makes UI updates much faster and more efficient."
  
  ✨ 
  "For example, when a user types into a form, 
  React doesn't re-render the whole page — just the part that changed. 
  The virtual DOM helps identify that change 
  and updates only that specific node in the real DOM."




  `,
    ],
