// features/ui/uiSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface UIState {
  // 🎛️ UI Flags
  isModalOpen: boolean;
  isSidebarVisible: boolean;
  isDarkMode: boolean;
  activeTab: string;
  isTooltipVisible: boolean;
  isToastVisible: boolean;
  focusedField: string | null;
  currentStep: number;
  openAccordionId: string | null;
  openDropdownId: string | null;
  isScrollLocked: boolean;
  keyboardShortcutsEnabled: boolean;

  // 🔄 Local Workflows
  wizardProgress: number;
  searchQuery: string;
  selectedItems: string[];
  draftContent: string;
  publishState: 'draft' | 'preview' | 'published';
  uploadProgress: number;
  themeVariant: 'light' | 'dark' | 'system';
  pinnedItemIds: string[];
  breadcrumbs: string[];
  visibleColumns: string[];
  dragItemId: string | null;

  // 💫 Transitions
  pageTransition: 'none' | 'fade' | 'slide';
  isLoading: boolean;
  animationTrigger: string | null;
  transitionComplete: boolean;
  isOverlayVisible: boolean;

  // ⚙️ Client Side Effect Flags
  localStorageSynced: boolean;
  userPrefsSynced: boolean;
  clipboardContent: string;
  debouncedInput: string;
  validationDelayActive: boolean;
  isIdle: boolean;
  countdownSeconds: number;
  showNotification: boolean;
  alertMessage: string | null;
  fileReadReady: boolean;
  offlineQueue: string[];
}

const initialState: UIState = {
  // UI flags
  isModalOpen: false,
  isSidebarVisible: true,
  isDarkMode: false,
  activeTab: 'home',
  isTooltipVisible: false,
  isToastVisible: false,
  focusedField: null,
  currentStep: 0,
  openAccordionId: null,
  openDropdownId: null,
  isScrollLocked: false,
  keyboardShortcutsEnabled: true,

  // Local workflows
  wizardProgress: 0,
  searchQuery: '',
  selectedItems: [],
  draftContent: '',
  publishState: 'draft',
  uploadProgress: 0,
  themeVariant: 'system',
  pinnedItemIds: [],
  breadcrumbs: [],
  visibleColumns: [],
  dragItemId: null,

  // Transitions
  pageTransition: 'none',
  isLoading: false,
  animationTrigger: null,
  transitionComplete: false,
  isOverlayVisible: false,

  // Side-effect flags
  localStorageSynced: false,
  userPrefsSynced: false,
  clipboardContent: '',
  debouncedInput: '',
  validationDelayActive: false,
  isIdle: false,
  countdownSeconds: 0,
  showNotification: false,
  alertMessage: null,
  fileReadReady: false,
  offlineQueue: [],
};

const uiSlice = createSlice({
  name: 'ui',
  initialState,
  reducers: {
    // 🔧 Toggle flags
    toggleModal: (s) => { s.isModalOpen = !s.isModalOpen },
    toggleSidebar: (s) => { s.isSidebarVisible = !s.isSidebarVisible },
    toggleDarkMode: (s) => { s.isDarkMode = !s.isDarkMode },

    // 🪄 Setters
    setActiveTab: (s, a: PayloadAction<string>) => { s.activeTab = a.payload },
    setFocusedField: (s, a: PayloadAction<string | null>) => { s.focusedField = a.payload },
    setCurrentStep: (s, a: PayloadAction<number>) => { s.currentStep = a.payload },
    setOpenAccordion: (s, a: PayloadAction<string | null>) => { s.openAccordionId = a.payload },
    setOpenDropdown: (s, a: PayloadAction<string | null>) => { s.openDropdownId = a.payload },
    setSearchQuery: (s, a: PayloadAction<string>) => { s.searchQuery = a.payload },
    setPublishState: (s, a: PayloadAction<'draft' | 'preview' | 'published'>) => { s.publishState = a.payload },
    setUploadProgress: (s, a: PayloadAction<number>) => { s.uploadProgress = a.payload },
    setThemeVariant: (s, a: PayloadAction<'light' | 'dark' | 'system'>) => { s.themeVariant = a.payload },
    setBreadcrumbs: (s, a: PayloadAction<string[]>) => { s.breadcrumbs = a.payload },
    setVisibleColumns: (s, a: PayloadAction<string[]>) => { s.visibleColumns = a.payload },
    setDragItem: (s, a: PayloadAction<string | null>) => { s.dragItemId = a.payload },
    setPageTransition: (s, a: PayloadAction<'none' | 'fade' | 'slide'>) => { s.pageTransition = a.payload },
    setLoading: (s, a: PayloadAction<boolean>) => { s.isLoading = a.payload },
    setAnimationTrigger: (s, a: PayloadAction<string | null>) => { s.animationTrigger = a.payload },
    setTransitionComplete: (s, a: PayloadAction<boolean>) => { s.transitionComplete = a.payload },
    setOverlayVisible: (s, a: PayloadAction<boolean>) => { s.isOverlayVisible = a.payload },

    // ✨ Client-side effects
    setClipboardContent: (s, a: PayloadAction<string>) => { s.clipboardContent = a.payload },
    setDebouncedInput: (s, a: PayloadAction<string>) => { s.debouncedInput = a.payload },
    setValidationDelay: (s, a: PayloadAction<boolean>) => { s.validationDelayActive = a.payload },
    setIdle: (s, a: PayloadAction<boolean>) => { s.isIdle = a.payload },
    setCountdown: (s, a: PayloadAction<number>) => { s.countdownSeconds = a.payload },
    setNotificationShown: (s, a: PayloadAction<boolean>) => { s.showNotification = a.payload },
    setAlertMessage: (s, a: PayloadAction<string | null>) => { s.alertMessage = a.payload },
    setFileReadReady: (s, a: PayloadAction<boolean>) => { s.fileReadReady = a.payload },
    setLocalStorageSynced: (s, a: PayloadAction<boolean>) => { s.localStorageSynced = a.payload },
    setUserPrefsSynced: (s, a: PayloadAction<boolean>) => { s.userPrefsSynced = a.payload },

    // 🧺 Cart-like selection workflows
    selectItem: (s, a: PayloadAction<string>) => {
      if (!s.selectedItems.includes(a.payload)) s.selectedItems.push(a.payload);
    },
    deselectItem: (s, a: PayloadAction<string>) => {
      s.selectedItems = s.selectedItems.filter((id) => id !== a.payload);
    },
    clearSelectedItems: (s) => { s.selectedItems = [] },

    // ⭐ Pinning
    pinItem: (s, a: PayloadAction<string>) => {
      if (!s.pinnedItemIds.includes(a.payload)) s.pinnedItemIds.push(a.payload);
    },
    unpinItem: (s, a: PayloadAction<string>) => {
      s.pinnedItemIds = s.pinnedItemIds.filter((id) => id !== a.payload);
    },

    // 📤 Offline queue
    enqueueOffline: (s, a: PayloadAction<string>) => {
      s.offlineQueue.push(a.payload);
    },
    dequeueOffline: (s) => {
      s.offlineQueue.shift();
    },
  },
});

export const {
  toggleModal,
  toggleSidebar,
  toggleDarkMode,
  setActiveTab,
  setFocusedField,
  setCurrentStep,
  setOpenAccordion,
  setOpenDropdown,
  setSearchQuery,
  setPublishState,
  setUploadProgress,
  setThemeVariant,
  setBreadcrumbs,
  setVisibleColumns,
  setDragItem,
  setPageTransition,
  setLoading,
  setAnimationTrigger,
  setTransitionComplete,
  setOverlayVisible,
  setClipboardContent,
  setDebouncedInput,
  setValidationDelay,
  setIdle,
  setCountdown,
  setNotificationShown,
  setAlertMessage,
  setFileReadReady,
  setLocalStorageSynced,
  setUserPrefsSynced,
  selectItem,
  deselectItem,
  clearSelectedItems,
  pinItem,
  unpinItem,
  enqueueOffline,
  dequeueOffline,
} = uiSlice.actions;

export default uiSlice.reducer;


