`
I want cursor based pagination with server side rendering support.

let’s build a cursor-based pagination system using RTK Query with Next.js App Router and Server-Side Rendering (SSR) support. This is ideal for large or real-time datasets where offset-based pagination can be unreliable.

🧠 What Is Cursor-Based Pagination?
Instead of using page numbers (?page=2), cursor-based pagination uses a unique identifier (like createdAt or id) to fetch the next or previous chunk of data.

Example API response:

json
{
  "data": [ ... ],
  "paging": {
    "nextCursor": "abc123",
    "hasMore": true
  }
}
🧱 1. RTK Query Setup
ts
// features/posts/postsApi.ts
import { createApi, fetchBaseQuery } from '@reduxjs/toolkit/query/react';

interface Post {
  id: string;
  title: string;
}

interface CursorResponse {
  data: Post[];
  paging: {
    nextCursor: string | null;
    hasMore: boolean;
  };
}

export const postsApi = createApi({
  reducerPath: 'postsApi',
  baseQuery: fetchBaseQuery({ baseUrl: 'https://your-api.com/' }),
  endpoints: (builder) => ({
    getPosts: builder.query<CursorResponse, string | null>({
      query: (cursor) => 'posts?cursor=dollar{cursor ?? ''}',
    }),
  }),
});

export const { useGetPostsQuery } = postsApi;
🧩 2. Server Component with SSR
tsx
// app/posts/page.tsx
import { HydrationBoundary, dehydrate } from '@tanstack/react-query';
import { getServerSideClient } from '@/lib/reactQueryClient';
import { postsApi } from '@/features/posts/postsApi';
import PostsClient from './PostsClient';

export default async function PostsPage() {
  const queryClient = getServerSideClient();
  await queryClient.prefetchQuery(
    postsApi.endpoints.getPosts.initiate(null)
  );

  return (
    <HydrationBoundary state={dehydrate(queryClient)}>
      <PostsClient />
    </HydrationBoundary>
  );
}
🧠 3. Client Component with Cursor Navigation
tsx
'use client';
import { useState } from 'react';
import { useGetPostsQuery } from '@/features/posts/postsApi';

export default function PostsClient() {
  const [cursor, setCursor] = useState<string | null>(null);
  const { data, isFetching } = useGetPostsQuery(cursor);

  return (
    <div>
      <ul>
        {data?.data.map((post) => (
          <li key={post.id}>{post.title}</li>
        ))}
      </ul>

      {data?.paging.hasMore && (
        <button
          onClick={() => setCursor(data.paging.nextCursor)}
          disabled={isFetching}
        >
          Load More
        </button>
      )}
    </div>
  );
}
✅ Benefits of This Setup
Cursor-based pagination avoids skipping/duplicating items

SSR support via prefetchQuery + HydrationBoundary

RTK Query handles caching and revalidation

Client/server separation keeps your app fast and SEO-friendly

Would you like to add infinite scroll, back-button support, or cache previous cursors for "Load Previous" functionality? I can help you level this up into a full-featured pagination engine 🔁✨
`

